 "content": "from collections import deque


def transform(grid):
    """Fill background cells enclosed by the outline color with color 4."""
    h, w = len(grid), len(grid[0])
    outline = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The outline is the non-background color occurring as the long frame/lines;
    # in these tasks it is the less common of the two colors.
    colors = {v for row in grid for v in row}
    if len(colors) == 2:
        outline = min(colors, key=lambda v: sum(row.count(v) for row in grid))
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] != outline and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] != outline and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and not outside[nr][nc] and grid[nr][nc] != outline:
                outside[nr][nc] = True
                q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != outline and not outside[r][c]:
                out[r][c] = 4
    return out
